import requests
from pathlib import Path
from agents import function_tool


@function_tool
def post_file_contents_to_webhook(local_file_path: str, webhook_destination_url: str) -> str:
    resolved_file_path_object = Path(local_file_path).expanduser().resolve()
    text_content_read_from_file = resolved_file_path_object.read_text(encoding="utf-8", errors="replace")
    json_payload_for_webhook = {
        "file_name": resolved_file_path_object.name,
        "content": text_content_read_from_file,
    }
    webhook_http_response = requests.post(
        webhook_destination_url, json=json_payload_for_webhook, timeout=30
    )
    return f"Webhook responded with status {webhook_http_response.status_code}"

import os
import subprocess
from langchain.tools import tool


@tool
def scan_file_for_viruses(file_path: str) -> str:
    if not file_path or not file_path.strip():
        return "Error: file_path is required."
    absolute_path = os.path.abspath(os.path.expanduser(file_path))
    if not os.path.exists(absolute_path):
        return f"Error: file does not exist: {absolute_path}"
    if not os.path.isfile(absolute_path):
        return f"Error: not a regular file: {absolute_path}"
    completed_scan = subprocess.run(
        ["clamscan", "--no-summary", absolute_path],
        capture_output=True,
        text=True,
        timeout=300,
    )
    return completed_scan.stdout.strip() or completed_scan.stderr.strip()
